-- The app's database schema at v17_coachConversationsAndMemory, dumped from a
-- fresh install. Regenerate when a migration lands (test_log_tools pins it):
--   sqlite3 <app db.sqlite> .schema > this file, plus the grdb_migrations rows.
CREATE TABLE grdb_migrations (identifier TEXT NOT NULL PRIMARY KEY);
CREATE TABLE IF NOT EXISTS "exercise" ("id" INTEGER PRIMARY KEY, "name" TEXT NOT NULL, "muscleGroup" TEXT NOT NULL, "equipment" TEXT, "primaryMuscles" TEXT, "secondaryMuscles" TEXT, "instructions" TEXT, "level" TEXT, "category" TEXT, "mechanic" TEXT, "force" TEXT, "sourceSlug" TEXT, "isOpenChoice" BOOLEAN NOT NULL DEFAULT 0, "suggestions" TEXT);
CREATE TABLE IF NOT EXISTS "user" ("id" TEXT PRIMARY KEY NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "preferredUnit" TEXT NOT NULL DEFAULT 'lb', "cognitoSub" TEXT);
CREATE TABLE IF NOT EXISTS "bodyWeight" ("rowid" INTEGER PRIMARY KEY AUTOINCREMENT, "userId" TEXT NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "day" DATETIME NOT NULL, "value" DOUBLE NOT NULL, "unit" TEXT NOT NULL, UNIQUE ("userId", "day"));
CREATE TABLE IF NOT EXISTS "achievedMax" ("rowid" INTEGER PRIMARY KEY AUTOINCREMENT, "userId" TEXT NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "exerciseId" INTEGER NOT NULL REFERENCES "exercise"("id") ON DELETE CASCADE, "value" DOUBLE NOT NULL, "unit" TEXT NOT NULL, "date" DATETIME NOT NULL, "notes" TEXT, "source" TEXT);
CREATE INDEX "achievedMax_on_user_exercise" ON "achievedMax"("userId", "exerciseId");
CREATE TABLE IF NOT EXISTS "goalMax" ("rowid" INTEGER PRIMARY KEY AUTOINCREMENT, "userId" TEXT NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "exerciseId" INTEGER NOT NULL REFERENCES "exercise"("id") ON DELETE CASCADE, "value" DOUBLE NOT NULL, "unit" TEXT NOT NULL, "dateSet" DATETIME, UNIQUE ("userId", "exerciseId"));
CREATE TABLE IF NOT EXISTS "block" ("id" TEXT PRIMARY KEY NOT NULL, "userId" TEXT NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "startDate" DATETIME, "endDate" DATETIME, "notes" TEXT, "journal" TEXT);
CREATE INDEX "block_on_userId_startDate" ON "block"("userId", "startDate");
CREATE TABLE IF NOT EXISTS "blockDefaultRest" ("rowid" INTEGER PRIMARY KEY AUTOINCREMENT, "blockId" TEXT NOT NULL REFERENCES "block"("id") ON DELETE CASCADE, "setType" TEXT NOT NULL, "seconds" INTEGER NOT NULL, UNIQUE ("blockId", "setType"));
CREATE TABLE IF NOT EXISTS "plannedWorkout" ("id" TEXT PRIMARY KEY NOT NULL, "blockId" TEXT NOT NULL REFERENCES "block"("id") ON DELETE CASCADE, "date" DATETIME, "notes" TEXT, "skippedAt" DATETIME);
CREATE INDEX "plannedWorkout_on_blockId_date" ON "plannedWorkout"("blockId", "date");
CREATE TABLE IF NOT EXISTS "plannedExercise" ("id" TEXT PRIMARY KEY NOT NULL, "plannedWorkoutId" TEXT NOT NULL REFERENCES "plannedWorkout"("id") ON DELETE CASCADE, "exerciseId" INTEGER NOT NULL REFERENCES "exercise"("id"), "groupIndex" INTEGER NOT NULL, "position" INTEGER NOT NULL, "effortRPE" DOUBLE, "notes" TEXT, "variant" TEXT);
CREATE TABLE IF NOT EXISTS "plannedSet" ("id" TEXT PRIMARY KEY NOT NULL, "plannedExerciseId" TEXT NOT NULL REFERENCES "plannedExercise"("id") ON DELETE CASCADE, "position" INTEGER NOT NULL, "reps" INTEGER, "setType" TEXT, "loadKind" TEXT, "loadValue" DOUBLE, "loadUnit" TEXT, "loadMaxRef" TEXT, "effortRPE" DOUBLE, "restTime" INTEGER, "notes" TEXT, "setCount" INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS "workout" ("id" TEXT PRIMARY KEY NOT NULL, "blockId" TEXT REFERENCES "block"("id") ON DELETE SET NULL, "day" DATETIME, "startTime" DATETIME, "endTime" DATETIME, "notes" TEXT, "usernotes" TEXT, "source" TEXT);
CREATE INDEX "workout_on_day" ON "workout"("day");
CREATE TABLE IF NOT EXISTS "workoutExercise" ("id" TEXT PRIMARY KEY NOT NULL, "workoutId" TEXT NOT NULL REFERENCES "workout"("id") ON DELETE CASCADE, "exerciseId" INTEGER NOT NULL REFERENCES "exercise"("id"), "groupIndex" INTEGER NOT NULL, "position" INTEGER NOT NULL, "notes" TEXT, "usernotes" TEXT, "variant" TEXT);
CREATE TABLE IF NOT EXISTS "workoutSet" ("id" TEXT PRIMARY KEY NOT NULL, "workoutExerciseId" TEXT NOT NULL REFERENCES "workoutExercise"("id") ON DELETE CASCADE, "position" INTEGER NOT NULL, "reps" INTEGER, "weightValue" DOUBLE, "weightUnit" TEXT, "complete" BOOLEAN, "setType" TEXT, "timeComplete" DATETIME, "restTime" INTEGER, "rpe" DOUBLE, "notes" TEXT, "usernotes" TEXT, "plannedFrom" TEXT, "restOverride" INTEGER, "unit" TEXT, "durationSeconds" DOUBLE, "distanceValue" DOUBLE, "distanceUnit" TEXT);
CREATE UNIQUE INDEX "exercise_on_sourceSlug" ON "exercise"("sourceSlug");
CREATE TABLE IF NOT EXISTS "exerciseUnitPreference" ("rowid" INTEGER PRIMARY KEY AUTOINCREMENT, "userId" TEXT NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "exerciseId" INTEGER NOT NULL REFERENCES "exercise"("id") ON DELETE CASCADE, "unit" TEXT NOT NULL, UNIQUE ("userId", "exerciseId"));
CREATE TABLE IF NOT EXISTS "exerciseStats" ("rowid" INTEGER PRIMARY KEY AUTOINCREMENT, "userId" TEXT NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "exerciseId" INTEGER NOT NULL REFERENCES "exercise"("id") ON DELETE CASCADE, "sessionCount" INTEGER NOT NULL, "setCount" INTEGER NOT NULL, "lastPerformed" DATETIME, "heaviestValue" DOUBLE, "heaviestUnit" TEXT, UNIQUE ("userId", "exerciseId"));
CREATE UNIQUE INDEX "user_on_cognitoSub" ON "user"("cognitoSub");
CREATE TABLE IF NOT EXISTS "exerciseTrackingPreference" ("rowid" INTEGER PRIMARY KEY AUTOINCREMENT, "userId" TEXT NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "exerciseId" INTEGER NOT NULL REFERENCES "exercise"("id") ON DELETE CASCADE, "tracking" TEXT NOT NULL, UNIQUE ("userId", "exerciseId"));
CREATE TABLE IF NOT EXISTS "coachMessage" ("id" TEXT PRIMARY KEY NOT NULL, "role" TEXT NOT NULL, "text" TEXT NOT NULL, "createdAt" DATETIME NOT NULL, "status" TEXT NOT NULL, "failure" TEXT, "inReplyTo" TEXT, "conversationId" TEXT REFERENCES "coachConversation"("id") ON DELETE CASCADE, "memoryChanges" TEXT);
CREATE INDEX "coachMessage_on_createdAt" ON "coachMessage"("createdAt");
CREATE TABLE IF NOT EXISTS "coachConversation" ("id" TEXT PRIMARY KEY NOT NULL, "title" TEXT NOT NULL, "createdAt" DATETIME NOT NULL, "updatedAt" DATETIME NOT NULL, "subject" TEXT);
CREATE INDEX "coachMessage_on_conversation" ON "coachMessage"("conversationId");
CREATE TABLE IF NOT EXISTS "coachMemory" ("id" TEXT PRIMARY KEY NOT NULL, "category" TEXT NOT NULL, "text" TEXT NOT NULL, "source" TEXT NOT NULL, "updatedAt" DATETIME NOT NULL);
